//! Pending residual ordinals are not produced-value witnesses. The enclosing
//! loop resolves them only after canonical residual lowering records exits.
use super::*;
#[derive(Clone,Copy)]
pub(super) struct ExpressionPath{pub(super) count:usize,pub(super) residual:Option<usize>}
fn chain(head:Vec<ExpressionPath>,tail:Vec<ExpressionPath>)->Result<Vec<ExpressionPath>>{let mut result=Vec::new();for first in head{if first.residual.is_some(){if result.len()>=256{return Err(fail("the complete record loop exits exceed their finite source budget",None));}result.push(first);continue;}for second in &tail{if result.len()>=256{return Err(fail("the complete record loop exits exceed their finite source budget",None));}result.push(ExpressionPath{count:first.count+second.count,residual:second.residual});}}Ok(result)}
fn has_try(node:&Value,work:&mut usize)->Result<bool>{let mut pending=vec![node];while let Some(value)=pending.pop(){if !value.is_array()&&!value.is_object(){continue;}*work+=1;if *work>100000{return Err(fail("the complete record loop exits exceed their finite source budget",None));}if text(value,"k")=="math"&&text(value,"op")==super::super::standard_sum_completions::PRIVATE_TRY{return Ok(true);}match value{Value::Array(values)=>pending.extend(values),Value::Object(values)=>pending.extend(values.values()),_=>{}}}Ok(false)}
pub(super) fn expression_paths(parser:&RustParser,node:&Value,selected:&Counter,work:&mut usize,inspect:bool)->Result<Vec<ExpressionPath>>{
 if inspect&&!has_try(node,work)?{return Ok(counts(parser,node,selected,work)?.into_iter().map(|count|ExpressionPath{count,residual:None}).collect());}
 *work+=1;if *work>100000{return Err(fail("the complete record loop exits exceed their finite source budget",None));}
 let descend=|value:&Value,work:&mut usize|expression_paths(parser,value,selected,work,false);let value=||ExpressionPath{count:0,residual:None};let kind=text(node,"k");
 if kind=="math"&&text(node,"op")==super::super::standard_sum_completions::PRIVATE_TRY{let ordinal=text(node,"name").parse::<usize>().ok().filter(|index|index.to_string()==text(node,"name")).filter(|index|parser.standard_sum_try_attempts.get(*index).is_some_and(|attempt|attempt.failure_base.is_some())).ok_or_else(||fail("the loop residue needs its actual parsed question-mark source",None))?;let args=node["args"].as_array().filter(|args|args.len()==1).ok_or_else(||fail("the loop residue needs its actual complete operand",None))?;return chain(descend(&args[0]["value"],work)?,vec![value(),ExpressionPath{count:0,residual:Some(ordinal)}]);}
 if let Some(EffectSource::Write{target,..})=parser.owned_record_effect_source_parts(text(node,"op"),text(node,"name"),node["args"].as_array().map_or(0,Vec::len)){
  let rhs=&node["args"][0]["value"];let overlaps=target==selected.target||fields::test_rust_owned_record_field_descendant(target,&selected.target)||fields::test_rust_owned_record_field_descendant(&selected.target,target);
  let exact=if target==selected.target&&text(rhs,"k")=="binary"&&text(rhs,"op")=="sub"{let left=serde_json::from_value::<SExpr>(rhs["left"].clone()).map_err(|_|fail("the counter decrement needs its complete actual source place",None))?;let right=serde_json::from_value::<SExpr>(rhs["right"].clone()).map_err(|_|fail("the counter decrement needs its complete actual numeral",None))?;numeral(&right,"1")&&place(parser,&left).is_some_and(|place|place.slot.lexical==selected.lexical&&place.indices==selected.indices)}else{false};let error=rules::read_rust_owned_record_loop_write_error(overlaps,exact);if !error.is_empty(){return Err(fail(&error,None));}return Ok(descend(rhs,work)?.into_iter().map(|path|if path.residual.is_some(){path}else{ExpressionPath{count:path.count+usize::from(exact),..path}}).collect());
 }
 if nested_admission(parser,node).is_some(){return Ok(counts(parser,node,selected,work)?.into_iter().map(|count|ExpressionPath{count,residual:None}).collect());}
 if kind=="lambda"||kind=="propositionValue"||kind=="math"&&!crate::translation::rust_expression_completion_rules::read_rust_expression_completion_packet_operation(text(node,"op")).is_empty(){return Err(fail("this loop body needs its separate callable or quantified exit derivation",None));}
 if kind=="if"{let mut tail=descend(&node["then"],work)?;tail.extend(descend(&node["else"],work)?);return chain(descend(&node["cond"],work)?,tail);}
 if kind=="binary"&&["and","or"].contains(&text(node,"op")){let mut tail=vec![value()];tail.extend(descend(&node["right"],work)?);return chain(descend(&node["left"],work)?,tail);}
 if kind=="match"||kind=="match1"{let mut head=vec![value()];if kind=="match"{for child in node["scrutinees"].as_array().into_iter().flatten(){head=chain(head,descend(child,work)?)?;}}else{head=chain(head,descend(&node["scrutinee"],work)?)?;}let mut tail=Vec::new();for row in node[if kind=="match"{"rows"}else{"cases"}].as_array().into_iter().flatten(){let paths=descend(&row["body"],work)?;if tail.len()+paths.len()>256{return Err(fail("the complete record loop exits exceed their finite source budget",None));}tail.extend(paths);}return chain(head,tail);}
 let mut result=vec![value()];for child in children(node)?{result=chain(result,descend(child,work)?)?;}Ok(result)
}
